/* Scheduler includes. */
#include "FreeRTOS.h"
#include "task.h"

/* App includes. */
#include "app_main.h"

/* Demo includes. */
#include "mpu_demo.h"

#include <stdio.h>

void app_main( void )
{
    /* Start the MPU demo. */
    vStartMPUDemo();

    /* Start the scheduler. */
    vTaskStartScheduler();

    printf( "Returned from vTaskStartScheduler something bad had happened\n" );

    /* Should not get here. */
    for( ; ; )
    {
    }
}
